// Получаем JSON данные, которые n8n уже подготовил
const inputData = $input.first().json;
// Доступ к распарсенному телу запроса
const body = inputData.body;

// Проверки делаем напрямую по полям объекта body
const receivedCmd = body.cmd;
const receivedToken = body.crm_token ? body.crm_token.trim() : '';
const EXPECTED_TOKEN = 'my-secret-megafon-key-123';
const EXPECTED_CMD = 'history';

if (receivedCmd !== EXPECTED_CMD) {
  console.warn(`Received command '${receivedCmd}', expected '${EXPECTED_CMD}'. Ignoring.`);
  return []; // Останавливаем обработку
}

if (receivedToken !== EXPECTED_TOKEN) {
  console.error(`Unauthorized: Invalid token. Received: \"${receivedToken}\"`);
  return []; // Останавливаем обработку
}

const recordingLink = body.link || null;
if (!recordingLink) {
  console.warn(`No recording link (link parameter) found for call ID ${body.callid}. Skipping transcription.`);
   return []; // Останавливаем обработку
}

console.log('Successfully validated webhook body:', body);

// Формируем выходные данные, используя поля из body
const outputData = {
  megafon_callid: body.callid || null,
  recording_url: recordingLink, // Уже проверили, что не null
  phone_number: body.phone || null,
  user_extension: body.user || null,
  call_type: body.type || null,
  call_start_time: body.start || null,
  call_duration_seconds: body.duration ? parseInt(body.duration, 10) : null,
  call_status: body.status || null,
  diversion: body.diversion || null,
  ext: body.ext || null,
};

// Возвращаем данные для следующих узлов
return [{ json: outputData }];

