const items = $input.all();
const results = [];
for (const item of items) {
  const resultData = { ...item.json };
  // --- Начало блока форматирования времени ---
const startTimeUTCString = resultData.call_start_time; // Берем исходную строку времени
let formattedStartTime = 'Invalid Date'; // Значение по умолчанию на случай ошибки

// Проверяем, что строка существует и похожа на ожидаемый формат
if (startTimeUTCString && startTimeUTCString.length === 16 && startTimeUTCString.endsWith('Z')) {
  try {
    // Пересобираем строку в стандартный ISO формат, понятный new Date()
    const year = startTimeUTCString.substring(0, 4);
    const month = startTimeUTCString.substring(4, 6);
    const day = startTimeUTCString.substring(6, 8);
    const hour = startTimeUTCString.substring(9, 11);
    const minute = startTimeUTCString.substring(11, 13);
    const second = startTimeUTCString.substring(13, 15);
    const isoString = `${year}-${month}-${day}T${hour}:${minute}:${second}Z`;

    const dateObject = new Date(isoString);

    // Проверяем, что дата создалась корректно
    if (!isNaN(dateObject.getTime())) {
      // Форматируем в нужный вид по Москве (ru-RU для формата ДД.ММ.ГГГГ)
      formattedStartTime = dateObject.toLocaleString('ru-RU', {
        timeZone: 'Europe/Moscow', // Указываем московскую таймзону
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false // Используем 24-часовой формат
      });
      // Иногда toLocaleString добавляет запятую между датой и временем, убираем её
       formattedStartTime = formattedStartTime.replace(',', '');
    } else {
        console.warn(`Could not parse date from reconstructed string: "${isoString}"`);
    }
  } catch (e) {
    console.error(`Error formatting date string "${startTimeUTCString}":`, e);
  }
} else if (startTimeUTCString) {
     console.warn(`Unexpected date format received: "${startTimeUTCString}"`);
     formattedStartTime = `Unrecognized Format: ${startTimeUTCString}`; // Помечаем, если формат не тот
}

// Добавляем отформатированное время в результат (можно назвать поле по-другому)
resultData.call_start_time_formatted = formattedStartTime;
// --- Конец блока форматирования времени ---
  try {
    const contentString = item.json.message?.content;
    if (contentString) {
      const analysisJson = JSON.parse(contentString);
      resultData.analysis = analysisJson;
    } else {
      resultData.analysis_error = "message.content not found";
      resultData.analysis_raw = JSON.stringify(item.json.message);
    }
  } catch (error) {
    resultData.analysis_error = `Parse error: ${error.message}`;
    resultData.analysis_raw = item.json.message?.content;
  }
  results.push({ json: resultData });
}
return results;
